 const applyRent=(snapshot:Player[],idx:number,owner:number,rent:number,n:Notice)=>{const next=snapshot.map((p,i)=>i===idx?{...p,cash:p.cash-rent}:i===owner?{...p,cash:p.cash+rent}:p);setPlayers(next);setNotice(n);addLog(n);if(!requireSolvency(next,idx))finishLanding(snapshot[idx].ai)};
