 useEffect(()=>{const saved=localStorage.getItem("london-tycoon-lang");if(saved==="en"||saved==="zh")setLang(saved);const code=new URLSearchParams(location.search).get("room")?.toUpperCase()||"";if(code.length===6){setRoomCodeInput(code);try{const auth=JSON.parse(sessionStorage.getItem("london-room-auth")||"null") as RoomAuth|null;if(auth?.code===code){setRoomAuth(auth);if(auth.gameMode)setGameMode(auth.gameMode);if(auth.settings)setSettings(auth.settings);setScreen("lobby");return}}catch{}setOnlineAction("join");setScreen("online")}},[]);
 useEffect(()=>{if(!roomAuth||(screen!=="lobby"&&screen!=="game"))return;let cancel=false;const refresh=async()=>{try{const r=await fetch(`/api/rooms?code=${roomAuth.code}`,{cache:"no-store"}),d=await r.json();if(!r.ok)throw new Error(d.error);if(cancel)return;setRoomMembers(d.room.players);if(screen==="lobby"&&d.room.settings){const server=d.room.settings as GameSettings&{gameMode?:GameMode};setSettings(server);if(server.gameMode)setGameMode(server.gameMode)}if(d.room.updatedAt>remoteVersionRef.current&&!dirtyRef.current){remoteVersionRef.current=d.room.updatedAt;if(d.room.status==="active"&&d.room.gameState)applySharedGame(d.room.gameState)}}catch(e){if(!cancel)setOnlineError(e instanceof Error?e.message:"Connection lost.")}};refresh();const timer=setInterval(refresh,1200);return()=>{cancel=true;clearInterval(timer)}},[roomAuth?.code,screen]);
